'Delta': {'rev':61643,'fuel':10566,'swb':16161},
'United': {'rev':57063,'fuel':11756,'swb':16678},
'Southwest': {'rev':27483,'fuel':5812,'swb':12240},
'American': {'rev':54211,'fuel':11418,'swb':16021},
'Alaska': {'rev':11735,'fuel':2506,'swb':3588},
}

fuel_pct = {k: v['fuel']/v['rev']*100 for k,v in data.items()}
swb_pct = {k: v['swb']/v['rev']*100 for k,v in data.items()}

print("Fuel % of revenue (sorted lowest first):")
for k,v in sorted(fuel_pct.items(), key=lambda x:x[1]):
    print(k, round(v,2))

print("\nSWB % of revenue (sorted lowest first):")
for k,v in sorted(swb_pct.items(), key=lambda x:x[1]):
